async function request(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:body!==undefined?{'Content-Type':'application/json'}:{},body:body!==undefined?JSON.stringify({...body,language:"en"}):undefined});if(!r.headers.get('content-type')?.includes('application/json'))throw new Error("Please sign in again and retry.");const d=await r.json();if(!r.ok)throw new Error(uiError(d.error)||"The request could not be completed.");return d;}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function dayOf(row){return String(row.day||row.timestamp||row.start_datetime||'').slice(0,10);}
function records(type,day=$('day').value){return (state.data[type]||[]).filter(r=>dayOf(r)===day);}
function sample(type,day){const rows=records(type,day);return type==='sleep'?(rows.find(r=>r.type==='long_sleep')||rows[0]):rows[0];}
function duration(seconds){if(!Number.isFinite(seconds))return '—';const mins=Math.round(seconds/60);return mins>=60?Math.floor(mins/60)+" h "+mins%60+" min":mins+" min";}
function format(key,value){if(value===null||value===undefined)return "No data";if(durationFields.has(key)&&typeof value==='number')return duration(value);if(typeof value==='boolean')return value?"Yes":"No";if(typeof value==='number'){const n=Math.round(value*100)/100;if(key.includes('calories')||key==='calories')return n+' kcal';if(key==='temperature_deviation'||key==='temperature_trend_deviation')return (n>0?'+':'')+n+' ℃';if(key==='efficiency'||key==='average')return n+'%';if(key==='average_breath')return n+" breaths/min";if(['average_heart_rate','lowest_heart_rate','bpm'].includes(key))return n+" bpm";if(key==='average_hrv')return n+' ms';if(key.includes('distance')||key.endsWith('meters')||key==='meters_to_target')return n+" m";if(key==='vascular_age')return n+" years";if(key==='vo2_max')return n+' ml/kg/min';return String(n);}if(typeof value==='object')return JSON.stringify(value);if(/datetime|bedtime_start|bedtime_end|timestamp/.test(key)&&!isNaN(Date.parse(value)))return new Date(value).toLocaleString("en-US",{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});return enumNames[value]||String(value);}
const metrics=[["Sleep score",'daily_sleep','score'," pts"],["Readiness score",'daily_readiness','score'," pts"],["Sleep duration",'sleep','total_sleep_duration',''],["Average HRV",'sleep','average_hrv','ms'],["Average nighttime heart rate",'sleep','average_heart_rate',"bpm"],["Lowest heart rate",'sleep','lowest_heart_rate',"bpm"],["Sleep efficiency",'sleep','efficiency','%'],["Deep sleep",'sleep','deep_sleep_duration',''],["REM sleep",'sleep','rem_sleep_duration',''],["Steps",'daily_activity','steps',"steps"],["Active energy",'daily_activity','active_calories','kcal'],["Estimated total energy",'daily_activity','total_calories','kcal']];
function renderSnapshot(){const box=$('snapshot');box.replaceChildren();for(const [label,type,key,unit] of metrics){const r=sample(type),value=r?.[key],card=document.createElement('button');card.type='button';card.onclick=()=>openMetric(label,type,key,unit);card.className='metric';const title=document.createElement('span');title.textContent=label;const number=document.createElement('b');number.textContent=value==null?'—':durationFields.has(key)?duration(value):Math.round(value*10)/10;const u=document.createElement('small');u.textContent=value==null?'':unit;number.append(u);const hint=document.createElement('span');hint.className='muted';hint.textContent=value==null?"No record for this date":dayOf(r);card.append(title,number,hint);const spark=miniSpark(type,key);if(spark)card.append(spark);box.append(card);}set('date-note',prettyDay($('day').value)+" · Every measurement has a date.");renderWeek();renderRings();renderHero();}
const chartMetrics=[["Average HRV",'sleep','average_hrv','ms'],["Total sleep",'sleep','total_sleep_duration',"h"],["Sleep score",'daily_sleep','score'," pts"],["Readiness score",'daily_readiness','score'," pts"],["Average heart rate",'sleep','average_heart_rate',"bpm"],["Steps",'daily_activity','steps',"steps"],["Active energy",'daily_activity','active_calories','kcal'],["High-stress time",'daily_stress','stress_high',"h"],["Temperature deviation",'daily_readiness','temperature_deviation','℃']];
function chart(){const [title,type,key,unit]=chartMetrics[Number($('trend-metric').value)];const byDay=new Map();for(const r of (state.data[type]||[]).slice().reverse()){if(typeof r[key]!=='number'||type==='sleep'&&r.type!=='long_sleep')continue;byDay.set(dayOf(r),{day:dayOf(r),value:durationFields.has(key)?r[key]/3600:r[key]});}const points=[...byDay.values()].sort((a,b)=>a.day.localeCompare(b.day));const box=$('trend');box.replaceChildren();if(points.length<2){box.textContent="At least two days of valid records are needed to show a trend.";set('trend-summary','');return;}let min=Infinity,max=-Infinity;for(const p of points){min=Math.min(min,p.value);max=Math.max(max,p.value);}const pad=max===min?1:(max-min)*.15;min-=pad;max+=pad;const svgNS='http://www.w3.org/2000/svg';const svg=document.createElementNS(svgNS,'svg');svg.setAttribute('viewBox','0 0 440 170');svg.setAttribute('class','chart');svg.setAttribute('role','img');svg.setAttribute('aria-label',title+'，'+points[0].day+" to "+points.at(-1).day);const t0=Date.parse(points[0].day),t1=Date.parse(points.at(-1).day);const coords=points.map(p=>({x:35+370*(Date.parse(p.day)-t0)/(t1-t0||1),y:135-110*(p.value-min)/(max-min)}));const poly=document.createElementNS(svgNS,'polyline');poly.setAttribute('points',coords.map(p=>p.x+','+p.y).join(' '));svg.append(poly);for(let i=0;i<points.length;i++){const dot=document.createElementNS(svgNS,'circle');dot.setAttribute('cx',coords[i].x);dot.setAttribute('cy',coords[i].y);dot.setAttribute('r','2.5');dot.setAttribute('tabindex','0');dot.setAttribute('aria-label',points[i].day+' '+points[i].value.toFixed(1)+' '+unit);dot.onclick=()=>{chooseDay(points[i].day);toast(points[i].day+' · '+points[i].value.toFixed(1)+' '+unit);};dot.onkeydown=e=>{if(e.key==='Enter')dot.onclick();};const tip=document.createElementNS(svgNS,'title');tip.textContent=points[i].day+'：'+points[i].value.toFixed(1)+' '+unit;dot.append(tip);svg.append(dot);}for(const [x,y,text] of [[5,22,max.toFixed(1)],[5,137,min.toFixed(1)],[35,163,points[0].day.slice(5)],[365,163,points.at(-1).day.slice(5)]]){const label=document.createElementNS(svgNS,'text');label.setAttribute('x',x);label.setAttribute('y',y);label.textContent=text;svg.append(label);}box.append(svg);const latest=Date.parse(points.at(-1).day),week=points.filter(p=>Date.parse(p.day)>latest-7*86400000),previous=points.filter(p=>Date.parse(p.day)<=latest-7*86400000&&Date.parse(p.day)>latest-14*86400000),mean=rows=>rows.reduce((s,p)=>s+p.value,0)/rows.length;let text=`${points.length} days with records · ${points[0].day} to ${points.at(-1).day}. Lines connect recorded dates; gaps do not imply measurements.`;if(previous.length){const delta=mean(week)-mean(previous);text+=` Latest 7-day recorded average: ${mean(week).toFixed(1)} ${unit}（${week.length} days); previous 7 days: ${mean(previous).toFixed(1)}（${previous.length} days); change: ${delta>0?'+':''}${delta.toFixed(1)}。`;}set('trend-summary',text);}
function statusFor(type){return state.statuses.find(r=>r.resource===type);}
function renderCoverage(){const box=$('coverage');box.replaceChildren();for(const [type,name] of Object.entries(names)){const row=document.createElement('div');row.className='coverage-row';const label=document.createElement('span');label.textContent=name;const count=document.createElement('span');count.textContent=(state.data[type]?.length||0)+" records";const hint=document.createElement('span');hint.className='muted';const s=statusFor(type);hint.textContent=({ok:"Synced",empty:"No records in this range",unauthorized:"Additional permission needed",partial:"Partially synced",error:"Could not load",rate_limited:"Retry later"})[s?.status]||"Not synced";hint.title=s?`${uiText(s.detail)} · ${s.updated_at}`:'';row.append(label,count,hint);box.append(row);}}
function datum(label,text){const e=document.createElement('div');e.className='datum';const a=document.createElement('span');a.textContent=label;const b=document.createElement('span');b.textContent=text;e.append(a,b);return e;}
function fields(container,record){const list=document.createElement('div');list.className='detail-grid';for(const [key,value] of Object.entries(record)){if(['id','ring_id','sleep_algorithm_version','period'].includes(key)||value==null)continue;if(value&&typeof value==='object'&&!Array.isArray(value)){const detail=document.createElement('details');const summary=document.createElement('summary');summary.textContent=fieldNames[key]||key;detail.append(summary);fields(detail,value);list.append(detail);}else list.append(datum(fieldNames[key]||key,format(key,value)));}container.append(list);}
function renderData(){const box=$('data-panels');box.replaceChildren();for(const type of Object.keys(names)){if(selectedGroup!=='all'&&!groups[selectedGroup].includes(type))continue;const panel=document.createElement('article');panel.className='card';const detail=document.createElement('details');const summary=document.createElement('summary');summary.className='data-panel-summary';const title=document.createElement('h2');title.textContent=names[type];const rows=records(type),hint=document.createElement('small');hint.textContent=rows.length?(rows[0].score!=null?rows[0].score+" min":rows.length+" records"):"No record";summary.append(title,hint);detail.append(summary);if(!rows.length){const p=document.createElement('p');p.className='muted';p.textContent=uiError(statusFor(type)?.detail)||"No records for this date. Try syncing first.";detail.append(p);}else if(type==='heartrate'){const values=rows.map(r=>r.bpm).filter(Number.isFinite);detail.append(datum("Sample count",String(rows.length)));if(values.length){let min=Infinity,max=-Infinity,total=0;for(const v of values){min=Math.min(min,v);max=Math.max(max,v);total+=v;}detail.append(datum("Heart rate range",min+'–'+max+" bpm"),datum("Sample average",(total/values.length).toFixed(1)+" bpm"));}const p=document.createElement('p');p.className='muted';p.textContent="Samples include different measurement contexts and are not resting heart rate.";detail.append(p);}else for(const [i,r] of rows.entries()){if(rows.length>1){const sub=document.createElement('h3');sub.textContent="Record "+(i+1);detail.append(sub);}fields(detail,r);}const ask=document.createElement('button');ask.className='text-button';ask.textContent="Ask Health Care Agent ↗";ask.onclick=()=>promptChat("Help me understand "+$('day').value+" · "+names[type]+". What should I pay attention to? Start with the main point.");detail.append(ask);panel.append(detail);box.append(panel);}}
async function loadHealth(){state=await request('health?days='+$('range').value);const days=[...new Set(Object.values(state.data).flat().map(dayOf).filter(Boolean))].sort();if(!$('day').value)$('day').value=(state.data.daily_sleep||[]).map(dayOf).sort().at(-1)||days.at(-1)||new Date().toLocaleDateString('en-CA');renderSnapshot();chart();renderCoverage();renderData();renderLatest();window.HealthCare?.refresh();set('global-status',(state.syncedAt?"Last synced: "+new Date(state.syncedAt).toLocaleString("en-US"):"No data synced yet")+(state.limitReached?" · Some records exceed the display limit. Choose a shorter range.":''));}
$('day').onchange=()=>{renderSnapshot();renderData();};$('range').onchange=()=>loadHealth().catch(e=>set('global-status',e.message));$('trend-metric').onchange=chart;
chartMetrics.forEach(([name,,,unit],i)=>{const o=document.createElement('option');o.value=i;o.textContent=name+' · '+unit;$('trend-metric').append(o);});for(const [key,name] of Object.entries(names)){const o=document.createElement('option');o.value=key;o.textContent=name;$('raw-resource').append(o);}
