let lastAutoSync=-Infinity,syncRetryAt=0,autoReady=false,refreshTimer=null;
try{syncRetryAt=Number(localStorage.getItem('hca-sync-retry-at'))||0;}catch{}
function syncLabel(text,issue=false){set('auto-sync-status',text);$('sync-dot').classList.toggle('working',busy);$('sync-dot').classList.toggle('issue',issue);}
async function syncHealth({automatic=false,live=false}={}){
 if(busy||!connected||document.hidden&&automatic)return;
 if(Date.now()<syncRetryAt){syncLabel("Oura rate limit reached. Retry after "+new Date(syncRetryAt).toLocaleTimeString("en-US",{hour:'2-digit',minute:'2-digit'})+".",true);return;}
 if(automatic&&Date.now()-lastAutoSync<45000)return;
 busy=true;lastAutoSync=Date.now();$('sync').disabled=true;$('refresh-latest').disabled=true;
 const resources=live?['heartrate','daily_stress','daily_activity']:['heartrate','daily_stress','daily_activity',...Object.keys(names).filter(r=>!['heartrate','daily_stress','daily_activity'].includes(r))];
 let good=0,failed=0,limited=false,processed=0;
 try{
  for(const resource of resources){
   if(automatic&&document.hidden)break;
   syncLabel((automatic?"Updating automatically":"Syncing")+' · '+names[resource]);
   try{const d=await request('oura/sync','POST',{resource,days:automatic&&state.syncedAt?7:Number($('range').value)});processed++;
    if(d.status==='rate_limited'){syncRetryAt=Date.now()+(d.retryAfterSeconds||300)*1000;try{localStorage.setItem('hca-sync-retry-at',String(syncRetryAt));}catch{}failed++;limited=true;break;}
    if(d.status==='ok'||d.status==='empty')good++;else failed++;
   }catch{failed++;processed++;}
   // Show the most recent samples first, without waiting for the historical resources.
   if(resource==='heartrate')await loadHealth();
  }
  await loadHealth();
  syncLabel(limited?"Oura rate limit reached; automatic sync paused":automatic&&document.hidden?"Paused; return to the app to resume":failed?"Updated "+good+" categories · "+failed+" categories incomplete":"Updated at "+new Date().toLocaleTimeString("en-US",{hour:'2-digit',minute:'2-digit'})+" · Syncs on open",failed>0);
  set('global-status',limited?"Some data is pending. Sync will retry later.":failed?"Some metrics are unavailable. See data coverage.":'');
 }catch(e){syncLabel("Not updated · "+e.message,true);}finally{busy=false;$('sync').disabled=!connected;$('refresh-latest').disabled=!connected;$('sync-dot').classList.remove('working');}
}
$('sync').onclick=()=>syncHealth();$('refresh-latest').onclick=()=>syncHealth({live:true});
function setupAutoSync(){
 const resume=()=>{if(autoReady&&!document.hidden)syncHealth({automatic:true});};
 document.addEventListener('visibilitychange',resume);window.addEventListener('pageshow',resume);window.addEventListener('online',resume);
 refreshTimer=setInterval(()=>{if(autoReady&&!document.hidden)syncHealth({automatic:true,live:true});},120000);
 window.addEventListener('pagehide',()=>{autoReady=false;});window.addEventListener('pageshow',()=>{autoReady=true;resume();});
}
