function renderMarkdown(container,text){container.replaceChildren();const inline=(parent,value)=>{const parts=value.split(/(\*\*[^*]+\*\*|`[^`]+`)/g);for(const part of parts){if(part.startsWith('**')&&part.endsWith('**')){const strong=document.createElement('strong');strong.textContent=part.slice(2,-2);parent.append(strong);}else if(part.startsWith('`')&&part.endsWith('`')){const code=document.createElement('code');code.textContent=part.slice(1,-1);parent.append(code);}else parent.append(document.createTextNode(part));}};let list=null,code=null;for(const line of text.split('\n')){if(line.startsWith('```')){if(code){code=null;}else{code=document.createElement('pre');container.append(code);}list=null;continue;}if(code){code.textContent+=line+'\n';continue;}if(!line.trim()){list=null;continue;}const bullet=line.match(/^\s*(?:[-*•]|\d+[.)、])\s+(.+)/);if(bullet){if(!list){list=document.createElement('ul');container.append(list);}const li=document.createElement('li');inline(li,bullet[1]);list.append(li);continue;}list=null;const heading=line.match(/^#{1,4}\s+(.+)/);const p=document.createElement(heading?'h3':'p');inline(p,heading?heading[1]:line);container.append(p);}}
function addMessage(role,text,options={}){const box=document.createElement('article');box.className='message '+role;box.dataset.text=text;const label=document.createElement('small');label.textContent=role==='user'?"You":'Health Care Agent';const body=document.createElement('div');body.className='message-body';if(role==='user')body.textContent=text;else renderMarkdown(body,text);box.append(label,body);if(options.image){const img=document.createElement('img');img.src=options.image;img.alt="Photo attached to this message";img.style.cssText='max-width:180px;max-height:180px;border-radius:12px;margin-top:9px';box.append(img);}if(role==='assistant'&&!options.streaming)messageActions(box,text);if(options.streaming)box.classList.add('streaming');$('messages').append(box);return box;}
function messageActions(box,text){const actions=document.createElement('div');actions.className='message-actions';const copy=document.createElement('button');copy.textContent="Copy";copy.onclick=async()=>{try{await navigator.clipboard.writeText(text);toast("Copied");}catch{toast("Could not copy. Select the text to copy it manually.");}};const remember=document.createElement('button');remember.textContent="Save to context";remember.onclick=async()=>{try{const current=await request('profile');const next=(current.text||'')+"\nA conversation excerpt I chose to keep (not verified facts):"+text;if(next.length>12000){toast("Your saved context is nearly full. Edit it in Journal before adding more.");return;}await request('profile','POST',{text:next});$('profile').value=next;toast("Saved to personal context for future conversations.");}catch(e){toast(e.message);}};actions.append(copy,remember);box.append(actions);}
function scrollChat(force=false){const el=$('chat-scroll');if(force||autoFollow){el.scrollTop=el.scrollHeight;$('jump-latest').hidden=true;autoFollow=true;}else $('jump-latest').hidden=false;}
function renderFollowups(){const box=$('followups');box.replaceChildren();if(!messages.length)return;for(const [label,text] of [["Explore this","I'd like to explore that point a little more."],["Say it plainly","Could you explain that more plainly?"],["What can I do today?","If I do just one thing today, what would you suggest?"]]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>promptChat(text);box.append(b);}}
function renderThreadList(){const box=$('thread-list');box.replaceChildren();for(const t of threadItems){const row=document.createElement('div');row.className='thread'+(t.id===activeThread?' active':'');const pick=document.createElement('button');pick.textContent=t.title;const date=document.createElement('small');date.textContent=new Date(t.updated_at).toLocaleDateString("en-US");pick.append(date);pick.onclick=async()=>{if(chatAbort){toast("Wait for this reply to finish, or stop it first.");return;}activeThread=t.id;try{localStorage.setItem('zhiji-active-thread',activeThread);}catch{}closeDialog('history-dialog');await loadChat();scrollChat(true);};const remove=document.createElement('button');remove.className='thread-delete';remove.textContent='×';remove.setAttribute('aria-label',"Delete conversation");remove.onclick=async()=>{if(chatAbort){toast("Stop the current reply first.");return;}if(!confirm("Delete “"+t.title+"”? Other conversations and journal entries will be kept."))return;try{await request('chat','DELETE',{threadId:t.id});if(activeThread===t.id)activeThread='legacy';await loadChat();}catch(e){toast(e.message);}};row.append(pick,remove);box.append(row);}if(!threadItems.length){const p=document.createElement('p');p.className='empty';p.textContent="Start with whatever is on your mind.";box.append(p);}}
async function loadChat(){let d;try{d=await request('chat?threadId='+encodeURIComponent(activeThread));}catch(e){if(activeThread!=='legacy'){activeThread='legacy';d=await request('chat?threadId=legacy');}else throw e;}messages=d.messages;threadItems=d.threads;olderCursor=d.cursor;chatHasMore=d.hasMore;$('older-messages').hidden=!d.hasMore;$('messages').replaceChildren();for(const m of messages)addMessage(m.role,m.text+(m.hasImage?"\n[This message had a photo; the photo was not retained]":''));$('chat-welcome').hidden=messages.length>0;const status=d.ready?"Connected · Ready to chat":"Model unavailable. Check Settings.";set('model-status',status);set('model-config-status',d.ready?"Model connected · "+d.model:"Model not configured");set('chat-subtitle',threadItems.find(t=>t.id===activeThread)?.title||"Your health in context. Your story heard.");try{localStorage.setItem('zhiji-active-thread',activeThread);}catch{}renderThreadList();renderFollowups();scrollChat(true);}
async function newChat(){if(chatAbort){toast("Wait for the reply to finish, or stop it first.");return;}try{const d=await request('chat','POST',{action:'new'});activeThread=d.thread.id;await loadChat();view('chat');closeDialog('history-dialog');$('question').value='';resizeComposer();toast("New conversation started. Earlier chats are in History.");}catch(e){toast(e.message);}}
async function olderMessages(){if(!olderCursor||!chatHasMore)return;const scroll=$('chat-scroll'),oldHeight=scroll.scrollHeight;try{const d=await request('chat?threadId='+encodeURIComponent(activeThread)+'&beforeTime='+encodeURIComponent(olderCursor.time)+'&beforeId='+encodeURIComponent(olderCursor.id));messages=[...d.messages,...messages];$('messages').replaceChildren();for(const m of messages)addMessage(m.role,m.text+(m.hasImage?"\n[This message had a photo; the photo was not retained]":''));olderCursor=d.cursor;chatHasMore=d.hasMore;$('older-messages').hidden=!d.hasMore;scroll.scrollTop=scroll.scrollHeight-oldHeight;}catch(e){toast(e.message);}}
async function consumeChat(response,onEvent){const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';try{while(true){const {value,done}=await reader.read();buffer+=done?decoder.decode():decoder.decode(value,{stream:true});buffer=buffer.replace(/\r\n/g,'\n');let boundary;while((boundary=buffer.indexOf('\n\n'))>=0){const chunk=buffer.slice(0,boundary);buffer=buffer.slice(boundary+2);const data=chunk.split('\n').filter(l=>l.startsWith('data:')).map(l=>l.slice(5).trimStart()).join('\n');if(data)onEvent(JSON.parse(data));}if(done)break;}}finally{reader.releaseLock();}}
function resizeComposer(){$('question').style.height='auto';$('question').style.height=Math.min(120,Math.max(33,$('question').scrollHeight))+'px';}
async function sendChat(){if(chatAbort)return;const question=$('question').value.trim()||(image?"Estimate this meal's calories. Start with a reasonable range.":'');if(!question)return;const sentImage=image;const controller=new AbortController();chatAbort=controller;lastSend={question,image:sentImage};autoFollow=true;$('send').hidden=true;$('stop-chat').hidden=false;$('chat-welcome').hidden=true;$('followups').replaceChildren();$('question').value='';resizeComposer();removeImage();set('chat-status',"Looking at your data and our conversation…");let userBox,assistantBox,answer='',finished=false;try{if(activeThread==='legacy'&&!messages.length){const d=await request('chat','POST',{action:'new'});activeThread=d.thread.id;try{localStorage.setItem('zhiji-active-thread',activeThread);}catch{}}userBox=addMessage('user',question,{image:sentImage});assistantBox=addMessage('assistant','',{streaming:true});const body=assistantBox.querySelector('.message-body');const typing=document.createElement('div');typing.className='typing';for(let i=0;i<3;i++)typing.append(document.createElement('i'));body.append(typing);scrollChat(true);const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:question,language:"en",image:sentImage,reportPeriod:reportData?reportPeriod:undefined,threadId:activeThread,days:Number($('range').value),timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone,style:$('chat-style').value,stream:true}),signal:controller.signal});if(!response.ok){const error=await response.json().catch(()=>({}));throw new Error(uiError(error.error)||"Could not connect. Please try again.");}await consumeChat(response,event=>{if(event.type==='delta'){answer+=event.text;renderMarkdown(body,answer);set('chat-status','');scrollChat();}else if(event.type==='done'){finished=true;set('chat-status',"Conversation saved. Keep going whenever you're ready.");const meta=document.createElement('div');meta.className='message-meta';meta.textContent="Based on recent health data and "+event.context.journalCount+" journal entries";assistantBox.append(meta);}else if(event.type==='error')throw new Error(uiError(event.error));});if(!finished)throw new Error("The reply was interrupted. Tap Retry to try again.");assistantBox.classList.remove('streaming');messageActions(assistantBox,answer);messages.push({role:'user',text:question},{role:'assistant',text:answer});renderFollowups();const latest=await request('chat?threadId='+encodeURIComponent(activeThread));threadItems=latest.threads;renderThreadList();set('chat-subtitle',threadItems.find(t=>t.id===activeThread)?.title||"Continue with Health Care Agent");}catch(e){assistantBox?.classList.remove('streaming');if(!answer)assistantBox?.remove();if(!finished){set('chat-status',e.name==='AbortError'?"Stopped. The incomplete reply was not saved.":e.message);const retry=document.createElement('button');retry.className='text-button';retry.textContent="↻ Retry message";retry.onclick=()=>{userBox?.remove();assistantBox?.remove();$('question').value=question;image=sentImage;if(image){$('attached-image').src=image;$('image-preview').hidden=false;}resizeComposer();sendChat();};$('followups').replaceChildren(retry);}}finally{chatAbort=null;$('send').hidden=false;$('stop-chat').hidden=true;scrollChat();}}
$('chat-form').onsubmit=e=>{e.preventDefault();sendChat();};$('question').oninput=resizeComposer;$('question').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&e.keyCode!==229){e.preventDefault();sendChat();}};$('stop-chat').onclick=()=>chatAbort?.abort();$('new-chat').onclick=newChat;$('history-new').onclick=newChat;$('open-history').onclick=()=>{renderThreadList();openDialog('history-dialog');};$('older-messages').onclick=olderMessages;$('chat-style').onchange=()=>{try{localStorage.setItem('zhiji-chat-style',$('chat-style').value);}catch{}toast(({natural:"Natural conversation",brief:"I'll keep it brief",detailed:"Let's look a little closer"})[$('chat-style').value]);};$('chat-scroll').onscroll=()=>{const el=$('chat-scroll');autoFollow=el.scrollHeight-el.scrollTop-el.clientHeight<140;$('jump-latest').hidden=autoFollow;};$('jump-latest').onclick=()=>scrollChat(true);$('chat-privacy').onclick=()=>openDialog('privacy-dialog');
function promptChat(text){view('chat');$('question').value=text;resizeComposer();$('question').focus();}
$('morning-chat').onclick=()=>promptChat("Looking at my recent data, what's one thing worth noticing today? Keep it conversational.");document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>promptChat(b.dataset.prompt));

function removeImage(){image=null;$('image-preview').hidden=true;$('attached-image').removeAttribute('src');$('chat-image').value='';}$('remove-image').onclick=removeImage;
$('chat-image').onchange=async()=>{const file=$('chat-image').files[0];if(!file)return;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error("Choose a JPG, PNG or WebP image");if(file.size>20000000)throw new Error("Choose a photo smaller than 20 MB");const bitmap=await createImageBitmap(file),ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const data=canvas.toDataURL('image/jpeg',.82);if(data.length>5000000)throw new Error("The compressed image is still too large. Crop it and retry.");image=data;$('attached-image').src=image;$('image-preview').hidden=false;set('chat-status',"Photo ready. It will upload only when you send your message.");}catch(e){set('chat-status',e.message);removeImage();}};
function localDateTime(){const d=new Date();return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}$('note-time').value=localDateTime();
async function loadNotes(){const d=await request('journal');noteEntries=d.entries;$('entries').replaceChildren();for(const n of noteEntries){const card=document.createElement('article');card.className='card entry';const top=document.createElement('div');top.className='section-heading';const date=document.createElement('small');date.textContent=new Date(n.time).toLocaleString("en-US");const remove=document.createElement('button');remove.className='text-button';remove.textContent="Delete";remove.onclick=async()=>{if(confirm("Delete this journal entry?"))try{await request('journal','DELETE',{id:n.id});await Promise.all([loadNotes(),loadCycles()]);}catch(e){set('note-status',e.message);}};top.append(date,remove);const text=document.createElement('p');text.textContent=n.text;const tags=document.createElement('div');tags.className='tags';tags.textContent=[({note:"Daily note",meal:"Food",weight:"Weight",mood:"Mood",exercise:"Exercise",cycle:"Cycle tracking",report:"Health reports"})[n.kind]||"Daily note",n.weight!=null?n.weight+' kg':'',n.mood!=null?"Mood "+n.mood+'/5':''].filter(Boolean).join(' · ');card.append(top,tags,text);if(n.nutrition){const macros=document.createElement('p');macros.className='meal-macros';macros.textContent=n.nutrition.kcal+" kcal · Protein "+n.nutrition.protein+"g · Carbs "+n.nutrition.carbs+"g · Fat "+n.nutrition.fat+'g';card.append(macros);}if(n.report){const summary=document.createElement('p');summary.className='muted';summary.textContent="Recorded "+n.report.coverage.mealCount+" meals · Workouts "+n.report.activity.workouts+" · Weight "+(n.report.weight.last??"Not recorded")+' kg';card.append(summary);} $('entries').append(card);}if(!noteEntries.length)set('entries',"No journal entries yet.");set('journal-summary',new Set(noteEntries.map(n=>new Date(n.time).toLocaleDateString())).size+" days of life in context.");renderTimeline();window.HealthCare?.refresh();}
$('journal-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await request('journal','POST',{text:$('note').value,time:new Date($('note-time').value).toISOString(),kind:$('note-kind').value,weight:$('weight').value?Number($('weight').value):undefined,mood:$('mood').value?Number($('mood').value):undefined});$('note').value='';$('weight').value='';$('mood').value='';set('note-status',"Encrypted and saved to the cloud.");await loadNotes();}catch(e){set('note-status',e.message);}finally{button.disabled=false;}};$('export-journal').onclick=()=>download(noteEntries,'zhiji-journal.json');
let oldNotes=[];try{const n=JSON.parse(localStorage.getItem('zhiji-notes-v1')||'[]');if(Array.isArray(n))oldNotes=n;}catch{}$('local-import').hidden=!oldNotes.length;
$('import-notes').onclick=async()=>{$('import-notes').disabled=true;try{for(const n of oldNotes){const bytes=new TextEncoder().encode(String(n.time)+'|'+String(n.text));const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');await request('journal','POST',{id:digest,time:n.time,text:n.text,kind:'note'});}$('local-import').hidden=true;await loadNotes();set('note-status',"Imported. Local originals are unchanged; importing again will not create duplicates.");}catch(e){set('note-status',e.message);}finally{$('import-notes').disabled=false;}};
$('save-profile').onclick=async()=>{try{await request('profile','POST',{text:$('profile').value});set('profile-status',"Saved. Future questions can use this context.");}catch(e){set('profile-status',e.message);}};
async function loadConnection(){const d=await request('oura/config');connected=d.connected;set('connection-badge',d.connected?"Oura connected":"Connect Oura");set('connection-state',d.connected?"Authorized. To add metrics, check your developer app permissions and authorize again.":d.configured?"App details saved. Authorize the connection to continue.":"Enter your Oura developer app details.");$('client-id').value=d.clientId||'';$('authorize').disabled=!d.configured;$('disconnect').hidden=!d.configured;$('sync').disabled=!d.connected;$('refresh-latest').disabled=!d.connected;if(!d.connected)syncLabel("Connect Oura in Settings first");return d;}
$('config-form').onsubmit=async e=>{e.preventDefault();try{const secret=$('client-secret').value;$('client-secret').value='';await request('oura/config','POST',{clientId:$('client-id').value,clientSecret:secret});await loadConnection();set('oura-status',"Saved. Please authorize again.");}catch(e){set('oura-status',e.message);}};
$('authorize').onclick=async()=>{try{const d=await request('oura/start','POST',{});location.assign(d.url);}catch(e){set('oura-status',e.message);}};
$('disconnect').onclick=async()=>{if(confirm("Delete Oura app details, tokens and all Oura data from this project? Journal entries and chats will be kept."))try{const d=await request('oura/disconnect','POST',{});alert(uiText(d.message));location.reload();}catch(e){set('oura-status',e.message);}};
let toastTimer;
function toast(text){set('toast',text);$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3200);}
function openDialog(id){const dialog=$(id);if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}
function closeDialog(id){const dialog=$(id);if(typeof dialog.close==='function')dialog.close();else dialog.removeAttribute('open');}
function localDay(d=new Date()){const p=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate());}
function prettyDay(day){const d=new Date(day+'T12:00:00');return Number.isFinite(d.getTime())?d.toLocaleDateString("en-US",{month:'long',day:'numeric',weekday:'long'}):day;}
function chooseDay(day){$('day').value=day;renderSnapshot();renderData();renderTimeline();}
function renderWeek(){const box=$('week-strip');box.replaceChildren();const anchor=new Date(($('day').value||localDay())+'T12:00:00'),known=new Set((state.data.daily_sleep||[]).map(dayOf));for(let i=6;i>=0;i--){const date=new Date(anchor);date.setDate(date.getDate()-i);const day=localDay(date),b=document.createElement('button');b.className='week-day'+(day===$('day').value?' active':'');const label=document.createElement('span');label.textContent=day===localDay()?"Today":date.toLocaleDateString("en-US",{weekday:'short'}).replace("",'');const num=document.createElement('b');num.textContent=date.getDate();const dot=document.createElement('i');dot.style.opacity=known.has(day)?'1':'0';b.setAttribute('aria-label',prettyDay(day));b.setAttribute('aria-pressed',String(day===$('day').value));b.append(label,num,dot);b.onclick=()=>chooseDay(day);box.append(b);}}
function renderRings(){const box=$('score-rings');box.replaceChildren();for(const [label,type,color] of [["Sleep",'daily_sleep','#ae9bc9'],["Readiness",'daily_readiness','#e5a48a'],["Activity",'daily_activity','#9eae96']]){const score=sample(type)?.score,button=document.createElement('button');button.className='score-card';button.style.setProperty('--ring',color);const graphic=document.createElement('div');graphic.className='score-graphic';const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 70 70');for(const name of ['track','progress']){const c=document.createElementNS('http://www.w3.org/2000/svg','circle');c.setAttribute('cx','35');c.setAttribute('cy','35');c.setAttribute('r','30');c.setAttribute('class',name);if(name==='progress')c.setAttribute('stroke-dasharray',score==null?'0 189':Math.max(0,Math.min(100,score))/100*189+' 189');svg.append(c);}const value=document.createElement('b');value.textContent=score??'—';graphic.append(svg,value);const copy=document.createElement('div');const title=document.createElement('strong');title.textContent=label;const date=document.createElement('small');date.textContent=score==null?"No record for this date":$('day').value.slice(5).replace('-',' / ');copy.append(title,date);button.append(graphic,copy);button.onclick=()=>openMetric(label+" score",type,'score'," pts");box.append(button);}}
function numericPoints(type,key){const map=new Map();for(const r of (state.data[type]||[]).slice().reverse()){if(typeof r[key]!=='number'||type==='sleep'&&r.type!=='long_sleep')continue;map.set(dayOf(r),{day:dayOf(r),value:r[key]});}return [...map.values()].sort((a,b)=>a.day.localeCompare(b.day));}
function miniSpark(type,key){const points=numericPoints(type,key).slice(-14);if(points.length<2)return null;let min=Infinity,max=-Infinity;for(const p of points){min=Math.min(min,p.value);max=Math.max(max,p.value);}const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 80 25');svg.setAttribute('class','mini-spark');svg.setAttribute('aria-hidden','true');const poly=document.createElementNS('http://www.w3.org/2000/svg','polyline');poly.setAttribute('points',points.map((p,i)=>(i/(points.length-1)*76+2)+','+(22-(p.value-min)/(max-min||1)*18)).join(' '));poly.setAttribute('fill','none');poly.setAttribute('stroke','var(--purple)');poly.setAttribute('stroke-width','1.5');poly.setAttribute('stroke-linecap','round');svg.append(poly);return svg;}
function renderHero(){const hour=new Date().getHours();set('greeting',hour<6?"It's late. Give yourself room to wind down.":hour<12?"Good morning. Let's check in with you.":hour<18?"Good afternoon. Take a moment for yourself.":"Good evening. How has today felt?");const sleep=sample('sleep'),score=sample('daily_readiness');set('hero-title',sleep?.total_sleep_duration!=null?"Listen to your body's story.":"Understand yourself a little better each day.");let text=sleep?.total_sleep_duration!=null?$('day').value.slice(5).replace('-',"/")+" · Sleep: "+duration(sleep.total_sleep_duration)+'。':"Your numbers and how you feel both matter.";if(score?.score!=null)text+=" Readiness: "+score.score+". Let's look at the recent pattern.";set('hero-insight',text);}
function openMetric(label,type,key,unit){set('metric-title',label);set('metric-day',prettyDay($('day').value));const row=sample(type),value=row?.[key];$('metric-value').replaceChildren();const big=document.createElement('span');big.textContent=value==null?'—':durationFields.has(key)?duration(value):Math.round(value*100)/100;const small=document.createElement('small');small.textContent=value==null?'':unit;$('metric-value').append(big,small);const points=numericPoints(type,key).filter(p=>p.day<$('day').value).slice(-7);if(value!=null&&points.length){const avg=points.reduce((sum,p)=>sum+p.value,0)/points.length,delta=value-avg;set('metric-comparison',"Previous "+points.length+" valid records averaged "+format(key,avg)+". This reading is "+(delta>=0?"higher":"lower")+" by "+format(key,Math.abs(delta))+". This shows a change, not its cause.");}else set('metric-comparison',value==null?"No measurement for this date. Choose another day or sync first.":"Not enough history for a comparison yet.");const chartIndex=chartMetrics.findIndex(([,t,k])=>t===type&&k===key);$('metric-chart').replaceChildren();if(chartIndex>=0){$('trend-metric').value=chartIndex;chart();const svg=$('trend').querySelector('svg');if(svg)$('metric-chart').append(svg.cloneNode(true));}$('metric-detail').replaceChildren();if(row){const keys=type==='sleep'?['bedtime_start','bedtime_end','deep_sleep_duration','rem_sleep_duration','average_hrv','lowest_heart_rate']:['day','score','temperature_deviation','steps'];for(const k of keys){if(row[k]!=null)$('metric-detail').append(datum(fieldNames[k]||k,format(k,row[k])));}}$('metric-ask').onclick=()=>{closeDialog('metric-dialog');promptChat("I'm looking at "+$('day').value+" · "+label+'（'+(value==null?"No record":format(key,value))+"). What does this mean compared with my usual pattern? Keep it brief.");};openDialog('metric-dialog');}
function renderTimeline(){const box=$('today-timeline');box.replaceChildren();const day=$('day').value||localDay(),items=noteEntries.filter(n=>localDay(new Date(n.time))===day).slice(0,3);const sleep=sample('sleep');if(sleep?.bedtime_end){const line=document.createElement('div');line.className='timeline-line';const time=document.createElement('small');time.textContent=format('bedtime_end',sleep.bedtime_end)+' · Oura';const text=document.createElement('p');text.textContent="Woke up after sleeping "+duration(sleep.total_sleep_duration);line.append(time,text);box.append(line);}for(const n of items){const line=document.createElement('div');line.className='timeline-line';const time=document.createElement('small');time.textContent=new Date(n.time).toLocaleTimeString("en-US",{hour:'2-digit',minute:'2-digit'})+' · '+(({note:"Daily note",meal:"Food",weight:"Weight",mood:"Mood",exercise:"Exercise",cycle:"Cycle tracking",report:"Health reports"})[n.kind]||"Daily note");const text=document.createElement('p');text.textContent=n.text.length>100?n.text.slice(0,100)+'…':n.text;line.append(time,text);box.append(line);}if(!items.length&&!sleep){const p=document.createElement('p');p.className='muted';p.textContent="No entries for this day. Add a note about sleep, food or what's on your mind.";box.append(p);}const mood=items.find(n=>n.kind==='mood'&&n.mood);document.querySelectorAll('[data-mood]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.mood)===mood?.mood));}
function setupExperience(){try{document.body.classList.toggle('dark',localStorage.getItem('zhiji-theme')==='dark');}catch{}$('theme-toggle').onclick=()=>{const dark=document.body.classList.toggle('dark');$('theme-toggle').textContent=dark?'☀':'☾';try{localStorage.setItem('zhiji-theme',dark?'dark':'light');}catch{}};$('go-today').onclick=()=>chooseDay(localDay());$('quick-food').onclick=()=>view('food');$('welcome-food').onclick=()=>$('chat-image').click();$('quick-weight').onclick=()=>{view('journal');$('note-kind').value='weight';$('weight').focus();$('note').placeholder="You can also note how you feel about today's weigh-in.";};$('quick-talk').onclick=()=>promptChat("I'd like to talk about how I'm feeling today. Please listen first.");document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeDialog(b.dataset.close));document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}}));document.querySelectorAll('[data-mood]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const mood=Number(b.dataset.mood),labels={1:"Struggling",2:"Low",3:"Okay",4:"Good",5:"Great"};await request('journal','POST',{text:"Today's mood: "+labels[mood],kind:'mood',mood,time:new Date().toISOString()});set('mood-saved',"Saved. Thank you for checking in.");await loadNotes();document.querySelectorAll('[data-mood]').forEach(x=>x.classList.toggle('selected',x===b));toast(mood<=2?"Saved. You can talk with Health Care Agent whenever you'd like.":"Today's mood is saved.");}catch(e){toast(e.message);}finally{b.disabled=false;}});const viewport=window.visualViewport;const fit=()=>{document.documentElement.style.setProperty('--app-height',(viewport?.height||window.innerHeight)+'px');const keyboard=!!viewport&&window.innerHeight-viewport.height>160&&document.activeElement?.tagName==='TEXTAREA';document.body.classList.toggle('keyboard-open',keyboard);};viewport?.addEventListener('resize',fit);window.addEventListener('resize',fit);$('question').addEventListener('focus',()=>setTimeout(fit,100));$('question').addEventListener('blur',()=>setTimeout(fit,100));fit();}

function heartSamples(){return (state.data.heartrate||[]).filter(r=>Number.isFinite(r.bpm)&&r.bpm>0&&Number.isFinite(Date.parse(r.timestamp))&&Date.parse(r.timestamp)<=Date.now()+60000).slice().sort((a,b)=>Date.parse(a.timestamp)-Date.parse(b.timestamp));}
function newestStress(){return (state.data.daily_stress||[]).filter(r=>CycleModel.validDate(r.day)&&r.day<=localDay()).slice().sort((a,b)=>b.day.localeCompare(a.day))[0];}
function measurementTime(value){return new Date(value).toLocaleString("en-US",{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});}
function sampleAge(timestamp){const min=Math.max(0,Math.floor((Date.now()-Date.parse(timestamp))/60000));return min<1?"Less than a minute ago":min<60?min+" min ago":min<1440?Math.floor(min/60)+" h ago":Math.floor(min/1440)+" days ago";}
function heartPlot(container,rows,large=false){
 container.replaceChildren();if(rows.length<2){if(large)container.textContent="At least two heart rate samples are needed to show a trend.";return;}
 const last=Date.parse(rows.at(-1).timestamp),points=rows.filter(r=>Date.parse(r.timestamp)>=last-6*3600000);if(points.length<2)return;
 const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox',large?'0 0 400 150':'0 0 300 28');svg.setAttribute('role','img');svg.setAttribute('aria-label',"Recent heart rate samples through "+measurementTime(last));
 const w=large?400:300,h=large?150:28,pad=large?20:3,start=Date.parse(points[0].timestamp),span=Math.max(1,last-start);let min=Infinity,max=-Infinity;for(const p of points){min=Math.min(min,p.bpm);max=Math.max(max,p.bpm);}const spread=Math.max(10,max-min);let path='',prev=0;
 for(const p of points){const t=Date.parse(p.timestamp),x=pad+(w-pad*2)*(t-start)/span,y=h-pad-(h-pad*2)*(p.bpm-min)/spread;path+=(prev&&t-prev<=1800000?' L':' M')+x.toFixed(1)+','+y.toFixed(1);prev=t;}
 const line=document.createElementNS(ns,'path');line.setAttribute('d',path);line.setAttribute('stroke','#ff375f');line.setAttribute('fill','none');line.setAttribute('stroke-width',large?'2.5':'2');line.setAttribute('stroke-linecap','round');svg.append(line);
 for(const p of points.filter((_,i)=>i===points.length-1||points.length<5)){const dot=document.createElementNS(ns,'circle');dot.setAttribute('cx',String(pad+(w-pad*2)*(Date.parse(p.timestamp)-start)/span));dot.setAttribute('cy',String(h-pad-(h-pad*2)*(p.bpm-min)/spread));dot.setAttribute('r',large?'3':'2');dot.setAttribute('fill','#ff375f');svg.append(dot);}
 if(large){svg.setAttribute('class','live-chart');for(const [x,value] of [[4,min],[4,max]]){const text=document.createElementNS(ns,'text');text.setAttribute('x',String(x));text.setAttribute('y',String(value===min?h-3:12));text.setAttribute('fill','currentColor');text.setAttribute('font-size','10');text.textContent=String(value);svg.append(text);}}container.append(svg);
}
function renderLatest(){
 const rows=heartSamples(),last=rows.at(-1);$('latest-bpm').replaceChildren();$('heart-mini-chart').replaceChildren();
 if(last){$('latest-bpm').append(document.createTextNode(String(last.bpm)+' '));const unit=document.createElement('small');unit.textContent="bpm";$('latest-bpm').append(unit);set('latest-heart-time',"Measured "+measurementTime(last.timestamp));const age=Date.now()-Date.parse(last.timestamp);set('heart-freshness',sampleAge(last.timestamp)+(age>1800000?" · Older data":" · Recent sample")+" · Not live");heartPlot($('heart-mini-chart'),rows);}
 else{set('latest-bpm','—');set('latest-heart-time',"No cloud heart rate samples yet");set('heart-freshness',statusFor('heartrate')?.status==='unauthorized'?"Heart rate permission needed":"Let the Oura app finish syncing first");}
 const stress=newestStress();$('stress-meter').hidden=true;
 if(stress){set('latest-stress-value',stress.stress_high==null?"No duration":duration(stress.stress_high));set('latest-stress-time',stress.day+" · Total high-stress time");if(Number.isFinite(stress.stress_high)&&Number.isFinite(stress.recovery_high)&&stress.stress_high+stress.recovery_high>0){$('stress-meter').hidden=false;$('stress-fill').style.width=(100*stress.stress_high/(stress.stress_high+stress.recovery_high))+'%';$('stress-meter').setAttribute('aria-label',"Relative high-stress and restored durations, not a live stress score");}}
 else{set('latest-stress-value',"No summary");set('latest-stress-time',statusFor('daily_stress')?.status==='unauthorized'?"Additional authorization needed":"Waiting for Oura cloud data");}
 set('today-heading',new Date().toLocaleDateString("en-US",{month:'long',day:'numeric',weekday:'long'}));
}
function openLatest(type){
 const heart=type==='heartrate',rows=heartSamples(),last=rows.at(-1),stress=newestStress();
 set('metric-title',heart?"Latest heart rate measurement":"Stress & recovery");set('metric-day',heart?(last?measurementTime(last.timestamp):"No measurement"):(stress?.day||"No summary"));
 set('metric-value',heart?(last?last.bpm+" bpm":'—'):(stress?.stress_high!=null?duration(stress.stress_high):'—'));
 set('metric-comparison',heart?"Latest uploaded sample; not the same as resting heart rate.":"Total high-stress time · Oura daily summary");$('metric-chart').replaceChildren();$('metric-detail').replaceChildren();
 if(heart){heartPlot($('metric-chart'),rows,true);if(last){$('metric-detail').append(datum("Latest measurement",measurementTime(last.timestamp)),datum("Sample age",sampleAge(last.timestamp)),datum("Measurement context",enumNames[last.source]||last.source||"Oura sample"));const first=rows.find(r=>Date.parse(r.timestamp)>=Date.parse(last.timestamp)-6*3600000);if(first)$('metric-detail').append(datum("Chart time range",measurementTime(first.timestamp)+' — '+measurementTime(last.timestamp)));}}
 else if(stress){fields($('metric-detail'),stress);const status=statusFor('daily_stress');if(status)$('metric-detail').append(datum("API fetch time",measurementTime(status.updated_at)));}
 const note=document.createElement('p');note.className='live-detail-note';note.textContent=heart?"Syncs when opened and requests cloud updates every 2 minutes while visible. This web app cannot read the ring over Bluetooth or trigger measurements; updates depend on the Oura app uploading data.":"The Oura API provides daily stress and recovery summaries, not the app's live stress curve. An older daily summary is not your current stress level.";$('metric-detail').append(note);
 $('metric-ask').onclick=()=>{closeDialog('metric-dialog');promptChat(heart?"Explain my latest uploaded heart rate, noting its time and measurement context. Start with the main point.":"Combine my latest daily stress summary with my journal. Highlight one change, distinguish dates, and do not treat it as live stress.");};openDialog('metric-dialog');
}
let cycleEntries=[],cycleMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);
const flowLabels={none:"No bleeding",spotting:"Spotting",light:"Light",medium:"Moderate",heavy:"Heavy"};
const symptomLabels={cramps:"Cramps",headache:"Headache",bloating:"Bloating",breast_tenderness:"Breast tenderness",fatigue:"Fatigue",low_mood:"Low mood",appetite_change:"Appetite changes",acne:"Acne"};
async function loadCycles(){const d=await request('cycle');cycleEntries=d.entries;renderCycle();}
function renderCycle(){
 const summary=CycleModel.summary(cycleEntries,localDay());
 set('cycle-home-title',summary.day?"Cycle day "+summary.day:"Get to know your rhythm");set('cycle-home-detail',summary.last?"Last start: "+summary.last+" · Log today":"Track periods, symptoms and changes");
 set('cycle-title',summary.day?"Cycle day "+summary.day:"Start with one entry");
 set('cycle-description',summary.next?(summary.next<localDay()?"Previous calendar estimate: "+summary.next+". No new start date has been recorded.":"Estimated next start: "+summary.next+". Actual timing may vary."):summary.variable?"Recent cycle lengths vary, so predictions are paused.":summary.last?"Last period started "+summary.last+". Add actual start dates; estimates need at least three starts.":"Record actual period start dates, flow and symptoms.");
 const stats=$('cycle-stats');stats.replaceChildren();for(const [label,value] of [["Last period start",summary.last||"Not recorded"],["Recent cycle length",summary.typical?summary.typical+" days (median)":"Not enough records"]]){const item=document.createElement('div'),b=document.createElement('b'),small=document.createElement('small');b.textContent=value;small.textContent=label;item.append(b,small);stats.append(item);}
 set('cycle-month',cycleMonth.toLocaleDateString("en-US",{year:'numeric',month:'long'}));const calendar=$('cycle-calendar');calendar.replaceChildren();const year=cycleMonth.getFullYear(),month=cycleMonth.getMonth(),offset=(new Date(year,month,1).getDay()+6)%7,total=new Date(year,month+1,0).getDate();
 for(let i=0;i<offset;i++)calendar.append(document.createElement('span'));
 for(let day=1;day<=total;day++){const date=localDay(new Date(year,month,day)),row=cycleEntries.find(r=>r.cycle.date===date)?.cycle,button=document.createElement('button');button.type='button';button.textContent=String(day);button.disabled=date>localDay();button.classList.toggle('today',date===localDay());button.classList.toggle('logged',!!row);button.classList.toggle('bleeding',!!row&&row.flow!=='none');button.classList.toggle('predicted',summary.next===date&&!row);button.setAttribute('aria-label',date+(row?'，'+flowLabels[row.flow]+(row.start?", start date":''):", no record")+(summary.next===date?", estimated calendar start":''));button.onclick=()=>openCycleEntry(date);calendar.append(button);}
 const history=$('cycle-history');history.replaceChildren();for(const entry of cycleEntries.slice(0,30)){const row=entry.cycle,button=document.createElement('button');button.className='cycle-history-row';const icon=document.createElement('span');icon.className='cycle-icon';icon.textContent=row.flow==='none'?'◌':'❋';const copy=document.createElement('span'),title=document.createElement('strong'),detail=document.createElement('small');title.textContent=row.date+' · '+flowLabels[row.flow]+(row.start?" · Start date":'');detail.textContent=row.symptoms.map(v=>symptomLabels[v]).join('、')||row.note||"Recorded";const arrow=document.createElement('b');arrow.textContent='›';copy.append(title,detail);button.append(icon,copy,arrow);button.onclick=()=>openCycleEntry(row.date);history.append(button);}if(!cycleEntries.length)history.textContent="No cycle records yet. Start by adding your latest period start date.";
}
function fillCycleEntry(date){
 const row=cycleEntries.find(e=>e.cycle.date===date)?.cycle;$('cycle-start').checked=!!row?.start;$('cycle-note').value=row?.note||'';
 document.querySelectorAll('input[name="flow"]').forEach(el=>el.checked=el.value===(row?.flow||'none'));document.querySelectorAll('input[name="symptom"]').forEach(el=>el.checked=!!row?.symptoms.includes(el.value));$('delete-cycle').hidden=!row;set('cycle-save-status','');
}
function openCycleEntry(date=localDay()){$('cycle-date').value=date;$('cycle-date').max=localDay();fillCycleEntry(date);openDialog('cycle-entry-dialog');}
function setupCycleUI(){
 $('open-cycle').onclick=()=>view('cycle');$('log-cycle-today').onclick=()=>openCycleEntry();$('cycle-prev').onclick=()=>{cycleMonth=new Date(cycleMonth.getFullYear(),cycleMonth.getMonth()-1,1);renderCycle();};$('cycle-next').onclick=()=>{cycleMonth=new Date(cycleMonth.getFullYear(),cycleMonth.getMonth()+1,1);renderCycle();};$('cycle-date').onchange=()=>fillCycleEntry($('cycle-date').value);
 $('ask-cycle').onclick=()=>promptChat("Looking at my cycle records, symptoms, sleep and heart rate, are there any recent changes worth noticing? Distinguish recorded facts from possibilities.");$('export-cycle').onclick=()=>download(cycleEntries,'health-care-agent-cycle.json');
 $('latest-heart').onclick=()=>openLatest('heartrate');$('latest-stress').onclick=()=>openLatest('daily_stress');
 document.querySelectorAll('input[name="flow"]').forEach(el=>el.onchange=()=>{if(['none','spotting'].includes(el.value))$('cycle-start').checked=false;});
 $('cycle-form').onsubmit=async e=>{e.preventDefault();$('save-cycle').disabled=true;$('delete-cycle').disabled=true;try{
  const date=$('cycle-date').value,flow=document.querySelector('input[name="flow"]:checked')?.value;if(!CycleModel.validDate(date)||date>localDay())throw Error("Choose today or an earlier date");
  if($('cycle-start').checked&&!['light','medium','heavy'].includes(flow))throw Error("Choose light, moderate or heavy flow for a period start");
  await request('cycle','POST',{date,flow,start:$('cycle-start').checked,symptoms:[...document.querySelectorAll('input[name="symptom"]:checked')].map(el=>el.value),note:$('cycle-note').value});await Promise.all([loadCycles(),loadNotes()]);closeDialog('cycle-entry-dialog');toast("Cycle entry saved and available as chat context.");
 }catch(e){set('cycle-save-status',e.message);}finally{$('save-cycle').disabled=false;$('delete-cycle').disabled=false;}};
 $('delete-cycle').onclick=async()=>{if(!confirm("Delete the cycle entry for this date?"))return;$('delete-cycle').disabled=true;$('save-cycle').disabled=true;try{await request('cycle','DELETE',{date:$('cycle-date').value});await Promise.all([loadCycles(),loadNotes()]);closeDialog('cycle-entry-dialog');toast("Entry for this date deleted.");}catch(e){set('cycle-save-status',e.message);}finally{$('delete-cycle').disabled=false;$('save-cycle').disabled=false;}};
}

let foodImage=null,foodEstimate=null,foodId=null,foodEdited=false,foodAnalyzing=false,reportPeriod='week',reportData=null;
async function prepareFoodPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>20000000)throw Error("Choose a JPG, PNG or WebP photo under 20 MB");const bitmap=await createImageBitmap(file),ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const result=canvas.toDataURL('image/jpeg',.82);if(result.length>5000000)throw Error("The photo is too large. Crop it and retry.");return result;}
function invalidateFood(){foodEstimate=null;foodId=null;$('food-result').hidden=true;}
