function setupFoodUI(){
 $('food-time').value=localDateTime();$('food-description').oninput=invalidateFood;$('food-photo').onchange=async()=>{const file=$('food-photo').files[0];if(!file)return;try{invalidateFood();foodImage=null;$('food-preview').hidden=true;foodImage=await prepareFoodPhoto(file);$('food-preview').src=foodImage;$('food-preview').hidden=false;$('food-remove-photo').hidden=false;set('food-status',"Photo ready. You can add portions and preparation details.");}catch(e){set('food-status',e.message);}};
 $('food-remove-photo').onclick=()=>{foodImage=null;$('food-photo').value='';$('food-preview').hidden=true;$('food-preview').removeAttribute('src');$('food-remove-photo').hidden=true;invalidateFood();};$('analyze-food').onclick=analyzeFood;
 for(const key of ['kcal','protein','carbs','fat'])$('food-'+key).oninput=()=>{foodEdited=true;set('food-range',"Edited manually. The values below will be saved.");};
 $('save-food').onclick=async()=>{if(!foodEstimate||!foodId)return;$('save-food').disabled=true;try{const nutrition={...foodEstimate.nutrition};for(const key of ['kcal','protein','carbs','fat']){const value=$('food-'+key).value;if(value===''||!Number.isFinite(Number(value))||Number(value)<0)throw Error("Check the nutrition values");nutrition[key]=Number(value);}if(foodEdited){delete nutrition.range;nutrition.assumptions+=" (values adjusted by the user)";}await request('journal','POST',{id:foodId,kind:'meal',time:new Date($('food-time').value).toISOString(),text:foodEstimate.title+($('food-description').value?'：'+$('food-description').value:''),nutrition});set('food-status',"Meal saved and included in weekly and monthly reports.");set('save-food',"Saved");await loadNotes();toast("Meal recorded.");}catch(e){set('food-status',e.message);$('save-food').disabled=false;}};
 document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{reportPeriod=b.dataset.report;document.querySelectorAll('[data-report]').forEach(el=>el.classList.toggle('selected',el===b));loadReport().catch(e=>set('report-status',e.message));});$('report-export').onclick=()=>{if(reportData)download(reportData,'health-care-agent-'+reportPeriod+'-'+reportData.to+'.json');};$('report-save').onclick=async()=>{try{$('report-save').disabled=true;await request('reports?period='+reportPeriod+'&timeZone='+encodeURIComponent(Intl.DateTimeFormat().resolvedOptions().timeZone),'POST',{});await loadNotes();toast("Report saved to Journal.");}catch(e){set('report-status',e.message);}finally{$('report-save').disabled=false;}};$('report-ask').onclick=()=>promptChat(reportPeriod==='morning'?"Based on my latest sleep data, how did I sleep and how might I approach today? State the sleep record date first.":"Please create a structured health report for the last "+(reportPeriod==='week'?7:30)+" days, covering nutrition, exercise, weight trends, sleep and one action to try next. Clearly state missing records.");
}
